import{_ as l,a0 as o,w as s,s as d,I as t,x as a,a1 as r,A as p,ao as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"15 個有用的 MySQL/MariaDB 性能調整和優化技巧 | LCTT x X-CMD","titleTemplate":false,"description":"15 個有用的 MySQL/MariaDB 性能調整和優化技巧 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"15 個有用的 MySQL/MariaDB 性能調整和優化技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"15 個有用的 MySQL/MariaDB 性能調整和優化技巧 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150626 15 Useful MySQL or MariaDB Performance Tuning and Optimization Tips","title":"15 個有用的 MySQL/MariaDB 性能調整和優化技巧","tag":"201506","desc":""},"relativePath":"201506/20150626 15 Useful MySQL or MariaDB Performance Tuning and Optimization Tips.md","filePath":"[post].md"}'),m={name:"201506/20150626 15 Useful MySQL or MariaDB Performance Tuning and Optimization Tips.md"};function y(c,e,M,S,u,L){const n=o("Link");return s(),d("div",null,[e[22]||(e[22]=t("h1",{id:"_15-個有用的-mysql-mariadb-性能調整和優化技巧",tabindex:"-1"},[a("15 個有用的 MySQL/MariaDB 性能調整和優化技巧 "),t("a",{class:"header-anchor",href:"#_15-個有用的-mysql-mariadb-性能調整和優化技巧","aria-label":"Permalink to “15 個有用的 MySQL/MariaDB 性能調整和優化技巧”"},"​")],-1)),e[23]||(e[23]=t("p",null,"MySQL 是一個強大的開源關係資料庫管理系統（簡稱 RDBMS）。它發佈於 1995 年（20年前）。它採用結構化查詢語言（SQL），這可能是資料庫內容管理中最流行的選擇。最新的 MySQL 版本是 5.6.25，於 2015 年 5 月 29 日發佈。",-1)),e[24]||(e[24]=t("p",null,"關於 MySQL 一個有趣的事實是它的名字來自於 Michael Widenius（MySQL 的創始人）的女兒“ My”。儘管有許多關於 MySQL 有趣的傳聞，不過本文主要是向你展示一些有用的實踐，以幫助你管理你的 MySQL 服務器。",-1)),e[25]||(e[25]=t("p",null,[t("img",{src:"http://www.tecmint.com/wp-content/uploads/2015/06/MySQL-Performance-Tuning1.png",alt:"MySQL 性能優化"})],-1)),e[26]||(e[26]=t("p",null,[t("em",null,"MySQL 性能優化")],-1)),e[27]||(e[27]=t("p",null,"2009 年 4 月，MySQL 被 Oracle 收購。其結果是MySQL 社區分裂，創建了一個叫 MariaDB 的分支 。創建該分支的主要原因是為了保持這個項目可以在 GPL 下的自由。",-1)),e[28]||(e[28]=t("p",null,"今天，MySQL 和 MariaDB 是用於類似 WordPress、Joomla、Magento 和其他 web 應用程序的最流行的 RDMS 之一（如果不是最多的）。",-1)),e[29]||(e[29]=t("p",null,"這篇文章將告訴你一些基本的，但非常有用的關於如何優化 MySQL/MariaDB 性能的技巧。注意，本文假定您已經安裝了 MySQL 或 MariaDB。如果你仍然不知道如何在系統上安裝它們，你可以按照以下説明去安裝：",-1)),t("ul",null,[t("li",null,[r(n,{href:"http://www.tecmint.com/install-lamp-in-centos-7/"},{default:p(()=>[...e[0]||(e[0]=[a("在 RHEL/CentOS 7 上安裝 LAMP",-1)])]),_:1})]),t("li",null,[r(n,{href:"http://www.tecmint.com/install-lamp-linux-apache-mysql-php-on-fedora-22/"},{default:p(()=>[...e[1]||(e[1]=[a("在 Fedora 22 上安裝 LAMP",-1)])]),_:1})]),t("li",null,[r(n,{href:"http://www.tecmint.com/install-lamp-on-ubuntu-15-04/"},{default:p(()=>[...e[2]||(e[2]=[a("在 Ubuntu 15.04 安裝 LAMP",-1)])]),_:1})]),t("li",null,[r(n,{href:"http://www.tecmint.com/install-mariadb-in-debian/"},{default:p(()=>[...e[3]||(e[3]=[a("在 Debian 8 上安裝 MariaDB",-1)])]),_:1})]),t("li",null,[r(n,{href:"http://www.tecmint.com/install-lemp-in-gentoo-linux/"},{default:p(()=>[...e[4]||(e[4]=[a("在 Gentoo Linux 上安裝 MariaDB",-1)])]),_:1})]),t("li",null,[r(n,{href:"http://www.tecmint.com/install-lamp-in-arch-linux/"},{default:p(()=>[...e[5]||(e[5]=[a("在 Arch Linux 上安裝 MariaDB",-1)])]),_:1})])]),e[30]||(e[30]=i(`<p><strong>重要提示</strong>： 在開始之前，不要盲目的接受這些建議。每個 MySQL 設置都是不同的，在進行任何更改之前需要慎重考慮。</p><p>你需要明白這些：</p><ul><li>MySQL/MariaDB 配置文件位於 <code>/etc/my.cnf</code>。 每次更改此文件後你需要重啓 MySQL 服務，以使更改生效。</li><li>這篇文章使用 MySQL 5.6 版本。</li></ul><h3 id="_1-啓用-innodb-的每張表一個數據文件設置" tabindex="-1">1. 啓用 InnoDB 的每張表一個數據文件設置 <a class="header-anchor" href="#_1-啓用-innodb-的每張表一個數據文件設置" aria-label="Permalink to “1. 啓用 InnoDB 的每張表一個數據文件設置”">​</a></h3><p>首先，有一個重要的解釋， InnoDB 是一個存儲引擎。MySQL 和 MariaDB 使用 InnoDB 作為默認存儲引擎。以前，MySQL 使用系統表空間來保存資料庫中的表和索引。這意味着服務器唯一的目的就是資料庫處理，它們的存儲盤不用於其它目的。</p><p>InnoDB 提供了更靈活的方式，它把每個資料庫的信息保存在一個 <code>.ibd</code> 數據文件中。每個 .idb 文件代表它自己的表空間。通過這樣的方式可以更快地完成類似 “TRUNCATE” 的資料庫操作，當刪除或截斷一個數據庫表時，你也可以回收未使用的空間。</p><p>這樣配置的另一個好處是你可以將某些資料庫表放在一個單獨的存儲設備。這可以大大提升你磁盤的 I/O 負載。</p><p>MySQL 5.6及以上的版本默認啓用 <code>innodb_file_per_table</code>。你可以在 /etc/my.cnf 文件中看到。該指令看起來是這樣的：</p><pre><code>innodb_file_per_table=1
</code></pre><h3 id="_2-將-mysql-資料庫數據存儲到獨立分區上" tabindex="-1">2. 將 MySQL 資料庫數據存儲到獨立分區上 <a class="header-anchor" href="#_2-將-mysql-資料庫數據存儲到獨立分區上" aria-label="Permalink to “2. 將 MySQL 資料庫數據存儲到獨立分區上”">​</a></h3><p><strong>注意</strong>：此設置只在 MySQL 上有效, 在 MariaDB 上無效。</p><p>有時候操作系統的讀/寫會降低你 MySQL 服務器的性能，尤其是如果操作系統和資料庫的數據位於同一塊磁盤上。因此，我建議你使用單獨的磁盤（最好是 SSD）用於 MySQL 服務。</p><p>要完成這步，你需要將新的磁盤連接到你的計算機/服務器上。對於這篇文章，我假定磁盤掛在到 /dev/sdb。</p><p>####下一步是準備新的分區：</p><pre><code># fdisk /dev/sdb
</code></pre><p>現在按 “N” 來創建新的分區。接着按 “P”，使其創建為主分區。在此之後，從 1-4 設置分區號。之後，你可以選擇分區大小。這裏按 enter。在下一步，你需要配置分區的大小。</p><p>如果你希望使用全部的磁盤，再按一次 enter。否則，你可以手動設置新分區的大小。準備就緒後按 “w” 保存更改。現在，我們需要為我們的新分區創建一個文件系統。這可以用下面命令輕鬆地完成：</p><pre><code># mkfs.ext4 /dev/sdb1
</code></pre><p>現在我們會掛載新分區到一個目錄。我在根目錄下創建了一個名為 “ssd” 的目錄：</p><pre><code># mkdir /ssd/
</code></pre><p>掛載新分區到剛才創建的目錄下：</p><pre><code># mount /dev/sdb1  /ssd/
</code></pre><p>你可以在 /etc/fstab 文件中添加如下行設置為開機自動掛載：</p><pre><code>/dev/sdb1 /ssd ext3 defaults 0 0
</code></pre><p>####現在我們將 MySQL 移動到新磁盤中</p><p>首先停止 MySQL 服務：</p><pre><code># service mysqld stop
</code></pre><p>我建議你​​同時停止 Apache/nginx，以防止任何試圖寫入資料庫的操作：</p><pre><code># service httpd stop
# service nginx stop
</code></pre><p>現在複製整個 MySQL 目錄到新分區中:</p><pre><code># cp /var/lib/mysql /ssd/ -Rp
</code></pre><p>這可能需要一段時間，具體取決於你的 MySQL 資料庫的大小。一旦這個過程完成後重命名 MySQL 目錄：</p><pre><code># mv /var/lib/mysql /var/lib/mysql-backup
</code></pre><p>然後創建一個符號鏈接：</p><pre><code># ln -s /ssd/mysql /var/lib/mysql
</code></pre><p>現在啓動你的 MySQL 和 web 服務：</p><pre><code># service mysqld start
# service httpd start
# service nginx start
</code></pre><p>以後你的資料庫將使用新的磁盤訪問。</p><h3 id="_3-優化使用-innodb-的緩衝池" tabindex="-1">3. 優化使用 InnoDB 的緩衝池 <a class="header-anchor" href="#_3-優化使用-innodb-的緩衝池" aria-label="Permalink to “3. 優化使用 InnoDB 的緩衝池”">​</a></h3><p>InnoDB 引擎在內存中有一個緩衝池用於緩存數據和索引。這當然有助於你更快地執行 MySQL/MariaDB 查詢語句。選擇合適的內存大小需要一些重要的決策並對系統的內存消耗有較多的認識。</p><p>下面是你需要考慮的:</p><ul><li>其它的進程需要消耗多少內存。這包括你的系統進程，頁表，套接字緩衝。</li><li>你的服務器是否專門用於 MySQL 還是你運行着其它非常消耗內存的服務。</li></ul><p>在一個專用的機器上，你可能會把 60-70％ 的內存分配給 <code>innodb_buffer_pool_size</code>。如果你打算在一個機器上運行更多的服務，你應該重新考慮專門用於 <code>innodb_buffer_pool_size</code> 的內存大小。</p><p>你需要設置 my.cnf 中的此項:</p><pre><code>innodb_buffer_pool_size
</code></pre><h3 id="_4-在-mysql-中避免使用-swappiness" tabindex="-1">4. 在 MySQL 中避免使用 Swappiness <a class="header-anchor" href="#_4-在-mysql-中避免使用-swappiness" aria-label="Permalink to “4. 在 MySQL 中避免使用 Swappiness”">​</a></h3><p>“交換”是一個當系統移動部分內存到一個稱為 “交換空間” 的特殊磁盤空間時的過程。通常當你的系統用完物理內存後就會出現這種情況，系統將信息寫入磁盤而不是釋放一些內存。正如你猜測的磁盤比你的內存要慢得多。</p><p>該選項默認情況下是啓用的：</p><pre><code># sysctl vm.swappiness 

vm.swappiness = 60
</code></pre><p>運行以下命令關閉 swappiness：</p><pre><code># sysctl -w vm.swappiness=0
</code></pre><h3 id="_5-設置-mysql-的最大連接數" tabindex="-1">5. 設置 MySQL 的最大連接數 <a class="header-anchor" href="#_5-設置-mysql-的最大連接數" aria-label="Permalink to “5. 設置 MySQL 的最大連接數”">​</a></h3><p><code>max_connections</code> 指令告訴你當前你的服務器允許多少併發連接。MySQL/MariaDB 服務器允許有 SUPER 權限的用户在最大連接之外再建立一個連接。只有當執行 MySQL 請求的時候才會建立連接，執行完成後會關閉連接並被新的連接取代。</p><p>請記住，太多的連接會導致內存的使用量過高並且會鎖住你的 MySQL 服務器。一般小網站需要 100-200 的連接數，而較大可能需要 500-800 甚至更多。這裏的值很大程度上取決於你 MySQL/MariaDB 的使用情況。</p><p>你可以動態地改變 <code>max_connections</code> 的值而無需重啓MySQL服務器：</p><pre><code># mysql -u root -p
mysql&gt; set global max_connections = 300;
</code></pre><h3 id="_6-配置-mysql-的線程緩存數量" tabindex="-1">6. 配置 MySQL 的線程緩存數量 <a class="header-anchor" href="#_6-配置-mysql-的線程緩存數量" aria-label="Permalink to “6. 配置 MySQL 的線程緩存數量”">​</a></h3><p><code>thread_cache_size</code> 指令用來設置你服務器緩存的線程數量。當客户端斷開連接時，如果當前線程數小於 <code>thread_cache_size</code>，它的線程將被放入緩存中。下一個請求通過使用緩存池中的線程來完成。</p><p>要提高服務器的性能，你可以設置 <code>thread_cache_size</code> 的值相對高一些。你可以通過以下方法來查看線程緩存命中率：</p><pre><code>mysql&gt; show status like &#39;Threads_created&#39;;
mysql&gt; show status like &#39;Connections&#39;;
</code></pre><p>你可以用以下公式來計算線程池的命中率：</p><pre><code>100 - ((Threads_created / Connections) * 100)
</code></pre><p>如果你得到一個較低的數字，這意味着大多數 mysql 連接使用新的線程，而不是從緩存加載。在這種情況下，你需要增加 <code>thread_cache_size</code>。</p><p>這裏有一個好處是可以動態地改變 <code>thread_cache_size</code> 而無需重啓 MySQL 服務。你可以通過以下方式來實現：</p><pre><code>mysql&gt; set global thread_cache_size = 16;
</code></pre><h3 id="_7-禁用-mysql-的-dns-反向查詢" tabindex="-1">7. 禁用 MySQL 的 DNS 反向查詢 <a class="header-anchor" href="#_7-禁用-mysql-的-dns-反向查詢" aria-label="Permalink to “7. 禁用 MySQL 的 DNS 反向查詢”">​</a></h3><p>默認情況下當新的連接出現時，MySQL/MariaDB 會進行 DNS 查詢解析用户的 IP 地址/主機名。對於每個客户端連接，它的 IP 都會被解析為主機名。然後，主機名又被反解析為 IP 來驗證兩者是否一致。</p><p>當 DNS 配置錯誤或服務器出現問題時，這很可能會導致延遲。這就是為什麼要關閉 DNS 的反向查詢的原因，你可以在你的配置文件中添加以下選項去設定：</p><pre><code>[mysqld]
# Skip reverse DNS lookup of clients
skip-name-resolve
</code></pre><p>更改後你需要重啓 MySQL 服務。</p><h3 id="_8-配置-mysql-的查詢緩存容量" tabindex="-1">8. 配置 MySQL 的查詢緩存容量 <a class="header-anchor" href="#_8-配置-mysql-的查詢緩存容量" aria-label="Permalink to “8. 配置 MySQL 的查詢緩存容量”">​</a></h3><p>如果你有很多重複的查詢並且數據不經常改變 – 請使用緩存查詢。 人們常常不理解 <code>query_cache_size</code> 的實際含義而將此值設置為 GB 級，這實際上會降低服務器的性能。</p><p>背後的原因是，在更新過程中線程需要鎖定緩存。通常設置為 200-300 MB應該足夠了。如果你的網站比較小的，你可以嘗試給 64M 並在以後及時去增加。</p><p>在你的 MySQL 配置文件中添加以下設置：</p><pre><code>query_cache_type = 1
query_cache_limit = 256K
query_cache_min_res_unit = 2k
query_cache_size = 80M
</code></pre><h3 id="_9-配置臨時表容量和內存表最大容量" tabindex="-1">9. 配置臨時表容量和內存表最大容量 <a class="header-anchor" href="#_9-配置臨時表容量和內存表最大容量" aria-label="Permalink to “9. 配置臨時表容量和內存表最大容量”">​</a></h3><p><code>tmp_table_size</code> 和 <code>max_heap_table_size</code> 這兩個變量的大小應該相同，它們可以讓你避免磁盤寫入。<code>tmp_table_size</code> 是內置內存表的最大空間。如果表的大小超出限值將會被轉換為磁盤上的 MyISAM 表。</p><p>這會影響資料庫的性能。管理員通常建議在服務器上設置這兩個值為每 GB 內存給 64M。</p><pre><code>[mysqld]
tmp_table_size= 64M
max_heap_table_size= 64M
</code></pre><h3 id="_10-啓用-mysql-慢查詢日誌" tabindex="-1">10. 啓用 MySQL 慢查詢日誌 <a class="header-anchor" href="#_10-啓用-mysql-慢查詢日誌" aria-label="Permalink to “10. 啓用 MySQL 慢查詢日誌”">​</a></h3><p>記錄慢查詢可以幫助你定位資料庫中的問題並幫助你調試。這可以通過在你的 MySQL 配置文件中添加以下值來啓用：</p><pre><code>slow-query-log = 1
slow-query-log-file = /var/lib/mysql/mysql-slow.log
long_query_time = 1
</code></pre><p>第一個變量啓用慢查詢日誌，第二個告訴 MySQL 實際的日誌文件存儲位置。使用 <code>long_query_time</code> 來定義完成 MySQL 查詢多少用時算長。</p><h3 id="_11-檢查-mysql-的空閒連接" tabindex="-1">11. 檢查 MySQL 的空閒連接 <a class="header-anchor" href="#_11-檢查-mysql-的空閒連接" aria-label="Permalink to “11. 檢查 MySQL 的空閒連接”">​</a></h3><p>空閒連接會消耗資源，可以的話應該被終止或者刷新。空閒連接是指處於 “sleep” 狀態並且保持了很長一段時間的連接。你可以通過運行以下命令查看空閒連接：</p><pre><code># mysqladmin processlist -u root -p | grep “Sleep”
</code></pre><p>這會顯示處於睡眠狀態的進程列表。當代碼使用持久連接到資料庫時會出現這種情況。使用 PHP 調用 mysql_pconnect 可以打開這個連接，執行完查詢之後，刪除認證信息並保持連接為打開狀態。這會導致每個線程的緩衝都被保存在內存中，直到該線程結束。</p><p>首先你要做的就是檢查代碼問題並修復它。如果你不能訪問正在運行的代碼，你可以修改 <code>wait_timeout</code> 變量。默認值是 28800 秒，而你可以安全地將其降低到 60 ：</p><pre><code>wait_timeout=60
</code></pre><h3 id="_12-為-mysql-選擇正確的文件系統" tabindex="-1">12. 為 MySQL 選擇正確的文件系統 <a class="header-anchor" href="#_12-為-mysql-選擇正確的文件系統" aria-label="Permalink to “12. 為 MySQL 選擇正確的文件系統”">​</a></h3><p>選擇正確的文件系統對資料庫至關重要。在這裏你需要考慮的最重要的事情是 - 數據的完整性，性能和易管理性。</p><p>按照 MariaDB 的建議，最好的文件系統是XFS、ext4 和 Btrfs。它們都是可以使用超大文件和大容量存儲卷的企業級日誌型文件系統。</p><p>下面你可以找到一些關於這三個文件系統的有用信息：</p><div class="table-wrap"><table><thead><tr><th>文件系統</th><th>XFS</th><th>Ext4</th><th>Btrfs</th></tr></thead><tbody><tr><td>文件系統最大容量</td><td>8EB</td><td>1EB</td><td>16EB</td></tr><tr><td>最大文件大小</td><td>8EB</td><td>16TB</td><td>16EB</td></tr></tbody></table></div>`,94)),t("p",null,[e[7]||(e[7]=a("我們的這篇文章詳細介紹了 Linux 文件系統的利與弊: ",-1)),r(n,{href:"http://www.tecmint.com/linux-file-system-explained/"},{default:p(()=>[...e[6]||(e[6]=[a("Linux 文件系統解析",-1)])]),_:1}),e[8]||(e[8]=a("。",-1))]),e[31]||(e[31]=i(`<h3 id="_13-設置-mysql-允許的最大數據包" tabindex="-1">13. 設置 MySQL 允許的最大數據包 <a class="header-anchor" href="#_13-設置-mysql-允許的最大數據包" aria-label="Permalink to “13. 設置 MySQL 允許的最大數據包”">​</a></h3><p>MySQL 把數據拆分成包。通常一個包就是發送到客户端的一行數據。<code>max_allowed_pa​​cket</code> 變量定義了可以被髮送的最大的包。</p><p>此值設置得過低可能會導致查詢速度變得非常慢，然後你會在 MySQL 的錯誤日誌看到一個錯誤。建議將該值設置為最大包的大小。</p><h3 id="_14-測試-mysql-的性能優化" tabindex="-1">14. 測試 MySQL 的性能優化 <a class="header-anchor" href="#_14-測試-mysql-的性能優化" aria-label="Permalink to “14. 測試 MySQL 的性能優化”">​</a></h3><p>你應該定期檢查 MySQL/MariaDB 的性能。這將幫助你瞭解資源的使用情況是否發生了改變或需要進行改進。</p><p>有大量的測試工具可用，但我推薦你一個簡單易用的。該工具被稱為 mysqltuner。</p><p>使用下面的命令下載並運行它：</p><pre><code># wget https://github.com/major/MySQLTuner-perl/tarball/master
# tar xf master
# cd major-MySQLTuner-perl-993bc18/
# ./mysqltuner.pl 
</code></pre><p>你將收到有關 MySQL 使用的詳細報告和推薦提示。下面是默認 MariaDB 安裝的輸出樣例：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/06/MySQL-Performance-Tuning.png" alt="MySQL 性能優化"></p><h3 id="_15-優化和修復-mysql-資料庫" tabindex="-1">15. 優化和修復 MySQL 資料庫 <a class="header-anchor" href="#_15-優化和修復-mysql-資料庫" aria-label="Permalink to “15. 優化和修復 MySQL 資料庫”">​</a></h3><p>有時候 MySQL/MariaDB 資料庫中的表很容易崩潰，尤其是服務器意外關機、文件系統突然崩潰或複製過程中仍然訪問資料庫。幸運的是，有一個稱為 &#39;mysqlcheck&#39; 的免費開源工具，它會自動檢查、修復和優化 Linux 中資料庫的所有表。</p><pre><code># mysqlcheck -u root -p --auto-repair --check --optimize --all-databases
# mysqlcheck -u root -p --auto-repair --check --optimize databasename
</code></pre><p>就是這些！我希望上述文章對你有用，並幫助你優化你的 MySQL 服務器。一如往常，如果你有任何疑問或評論，請在下面的評論部分提交。</p><hr>`,15)),t("p",null,[e[10]||(e[10]=a("via: ",-1)),r(n,{href:"http://www.tecmint.com/mysql-mariadb-performance-tuning-and-optimization/"},{default:p(()=>[...e[9]||(e[9]=[a("http://www.tecmint.com/mysql-mariadb-performance-tuning-and-optimization/",-1)])]),_:1})]),t("p",null,[e[14]||(e[14]=a("作者：",-1)),r(n,{href:"http://www.tecmint.com/author/marintodorov89/"},{default:p(()=>[...e[11]||(e[11]=[a("Marin Todorov",-1)])]),_:1}),e[15]||(e[15]=a(" 譯者：",-1)),r(n,{href:"https://github.com/strugglingyouth"},{default:p(()=>[...e[12]||(e[12]=[a("strugglingyouth",-1)])]),_:1}),e[16]||(e[16]=a(" 校對：",-1)),r(n,{href:"https://github.com/ictlyh"},{default:p(()=>[...e[13]||(e[13]=[a("ictlyh",-1)])]),_:1})]),t("p",null,[e[19]||(e[19]=a("本文由 ",-1)),r(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[17]||(e[17]=[a("LCTT",-1)])]),_:1}),e[20]||(e[20]=a(" 原創翻譯，",-1)),r(n,{href:"https://linux.cn/"},{default:p(()=>[...e[18]||(e[18]=[a("Linux中國",-1)])]),_:1}),e[21]||(e[21]=a(" 榮譽推出",-1))])])}const Q=l(m,[["render",y]]);export{b as __pageData,Q as default};
